action.command:
cd /tmp && node -e '
const fs = require("fs");
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/minimumReleaseAge/.test(m) && !/^\s*console|globalWarn/.test(m) && /(default|env|config|setting|fallback|??\?)/.test(m.replace(/\"/g,"")) ){
    // skip
  }
}
// simpler: print every occurrence line with surrounding context markers
let count=0;
for (let n=0;n<lines.length && count<60;n++){
  const m = lines[n];
  if (/minimumReleaseAge\b/.test(m)) { console.log(n, m.trim().slice(0,140)); count++; }
}
' 2>&1 | head -60

